/** Türkçe karakterleri sadeleştirip küçük harfe indirger — "Hakkâri" ≈ "hakkari". */
export function normalizeTR(s: string): string {
    return (s || '')
        .replace(/İ/g, 'i').replace(/I/g, 'ı')
        .toLowerCase()
        .replace(/â/g, 'a').replace(/î/g, 'i').replace(/û/g, 'u')
        .replace(/ç/g, 'c').replace(/ğ/g, 'g').replace(/ı/g, 'i')
        .replace(/ö/g, 'o').replace(/ş/g, 's').replace(/ü/g, 'u')
        .replace(/[^a-z0-9]/g, '');
}

export interface ResolvedCoords {
    lat: number;
    lon: number;
    /** Hangi hassasiyetle bulundu: ilçe > il > yok. */
    matched: 'district' | 'province' | null;
}

/**
 * Doğum yeri koordinatı çözümü: önce il+ilçe, sonra il, bulunamazsa null.
 * İsimler Türkçe-normalize edilerek karşılaştırılır (Hakkâri/Hakkari sorunu yok).
 */
export function resolveBirthCoords(city?: string, district?: string): ResolvedCoords | null {
    if (!city) return null;
    const nCity = normalizeTR(city);
    const province = TURKEY_GEO.find((p) => normalizeTR(p.name) === nCity);
    if (!province) return null;
    if (district) {
        const nDistrict = normalizeTR(district);
        const d = province.districts.find((x) => normalizeTR(x.name) === nDistrict)
            // "Merkez" ilçesi "<İl> Merkez" gibi yazılmış olabilir
            || province.districts.find((x) => normalizeTR(x.name) === nDistrict.replace(nCity, ''))
            || (nDistrict === 'merkez' || nDistrict === normalizeTR(city + ' Merkez')
                ? province.districts.find((x) => normalizeTR(x.name) === 'merkez')
                : undefined);
        if (d) return { lat: d.lat, lon: d.lon, matched: 'district' };
    }
    return { lat: province.lat, lon: province.lon, matched: 'province' };
}
